class Node:
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None

def insert(node, key):                   # O(h).
    if node is None:
        return Node(key)
    if key < node.key:
        node.left = insert(node.left, key)
    elif key > node.key:
        node.right = insert(node.right, key)
    return node                          # duplicates ignored by this spec.

def delete(node, key):                   # O(h).
    if node is None:
        return None
    if key < node.key:
        node.left = delete(node.left, key)
    elif key > node.key:
        node.right = delete(node.right, key)
    else:
        if node.left is None:            # zero or one child: splice.
            return node.right
        if node.right is None:
            return node.left
        succ = node.right                # two children: inorder successor.
        while succ.left is not None:
            succ = succ.left
        node.key = succ.key
        node.right = delete(node.right, succ.key)
    return node
```

| Delete case | Action |
|---|---|
| leaf. | return None to the parent. |
| one child. | return that child to the parent. |
| two children. | copy successor's key, delete successor from the right subtree. |

